UPDATE lambdas
SET description = #{description},
    metadata = #{metadata, typeHandler=dev.olegz.vf.registry.dao.handlers.ObjectMapTypeHandler}
WHERE lambda_id = #{lambdaId}

UPDATE lambdas
SET code_upload_id = #{uploadId}
WHERE lambda_id = #{lambdaId}

UPDATE lambdas
SET max_version = #{maxVersion}
WHERE lambda_id = #{lambdaId}

UPDATE lambdas
SET max_sequence = #{maxSequence}
WHERE lambda_id = #{lambdaId}

mapper.select:
SELECT b.lambda_id, b.name, b.description, b.metadata, b.dev_team_id, b.code_upload_id,
       b.created_at, b.max_version, b.max_sequence
FROM lambdas b
JOIN dev_team_members tm ON tm.dev_team_id = b.dev_team_id AND tm.user_id = #{userId}
WHERE lambda_id = #{lambdaId}

SELECT , t.name AS "developer_team_name"
FROM lambdas b
JOIN dev_teams t ON t.dev_team_id = b.dev_team_id
JOIN dev_team_members tm ON tm.dev_team_id = b.dev_team_id AND tm.user_id = #{userId}
AND t.dev_team_id = #{teamId}

SELECT 
FROM lambdas b
JOIN dev_team_members tm ON tm.dev_team_id = b.dev_team_id AND tm.user_id = #{userId}
WHERE b.lambda_id = #{lambdaId}
FOR UPDATE OF b

