UPDATE lambda_versions
SET status = #{status}, status_date = #{statusDate}, code_upload_id = #{codeUploadId}, arch = #{arch},
    schedule = #{schedule, typeHandler=dev.olegz.vf.registry.dao.handlers.StringMapTypeHandler},
    whatsnew = #{whatsnew}
WHERE lambda_version_id = #{lambdaVersionId}

